                                      lower_bound, initial_state};
    std::vector<torch::Tensor> outputs{output, final_state};
    c10::DeviceGuard guard(q.device());
    auto stream = c10_npu::getCurrentNPUStream(q.get_device()).stream(true);
    launch(inputs, outputs, stream);
}

